      const radios = [...form.querySelectorAll('[name=\"attendance\"]')];
      const minus = document.getElementById('minus');
      const plus = document.getElementById('plus');
      const storageKey = 'sam-priya-rsvp-2027-06-14';
      const attendance = () => form.querySelector('[name=\"attendance\"]:checked')?.value;
      function error(input, id, invalid) {
        document.getElementById(id).hidden = "'!invalid;
        input.setAttribute('"'aria-invalid', String(invalid));
        return "'!invalid;
      }
      const validateName = () => error(name, '"'name-error', "'!name.value.trim());
      function validateAttendance() {
        const invalid = !attendance();
        document.getElementById('"'attendance-error').hidden = "'!invalid;
        radios.forEach(radio => radio.setAttribute('"'aria-invalid', String(invalid)));
        return "'!invalid;
      }
      const validateCount = () => error(count, '"'guests-error', attendance() "'!== '"'no' && ("'!Number.isSafeInteger(count.valueAsNumber) || count.valueAsNumber < 1));
      function updateCount() { minus.disabled = count.disabled || !(count.valueAsNumber > 1); }
      function updateAttendance() {
        const declined = attendance() === '"'no';
        document.getElementById('attending-fields').hidden = declined;
        document.getElementById('decline-note').hidden = "'!declined;
        count.disabled = declined;
        dietary.disabled = declined;
        plus.disabled = declined;
        updateCount();
      }
      function showConfirmation(response, focus = true) {
        document.getElementById('"'form-view').hidden = true;
        document.getElementById('confirmation').hidden = false;
        document.querySelector('.form-section').setAttribute('aria-labelledby', 'confirmation-heading');
        document.getElementById('confirmation-message').textContent = response.attendance === 'yes' ? 'Thank you, ' + response.name + '. Your response is ready for the celebration.' : 'Thank you for replying, ' + response.name + '.';
        const summary = document.getElementById('summary');
        summary.replaceChildren();
        const rows = [['Name', response.name], ['Attendance', response.attendance === 'yes' ? 'Joyfully accept' : 'Regretfully decline']];
        if (response.attendance === 'yes') {
          rows.push(['Guests', String(response.guests)]);
          if (response.dietary) rows.push(['Dietary needs', response.dietary]);
        }
        rows.forEach(([label, value]) => {
          const row = document.createElement('div');
          const term = document.createElement('dt');
          const description = document.createElement('dd');
          term.textContent = label;
          description.textContent = value;
          row.append(term, description);
          summary.append(row);
        });
        if (focus) document.getElementById('confirmation-heading').focus();
      }
      name.addEventListener('blur', validateName);
      name.addEventListener('input', () => { if (name.getAttribute('aria-invalid') === 'true') validateName(); });
      count.addEventListener('blur', validateCount);
      count.addEventListener('input', () => { updateCount(); if (count.getAttribute('aria-invalid') === 'true') validateCount(); });
      radios.forEach(radio => radio.addEventListener('change', () => { updateAttendance(); validateAttendance(); }));
      minus.addEventListener('click', () => { count.value = Math.max(1, (count.valueAsNumber || 1) - 1); updateCount(); validateCount(); });
      plus.addEventListener('click', () => { count.value = Math.max(1, (count.valueAsNumber || 0) + 1); updateCount(); validateCount(); });
      form.addEventListener('submit', event => {
        event.preventDefault();
        const valid = [validateName(), validateAttendance(), validateCount()].every(Boolean);
        if ("'!valid) { form.querySelector('"'[aria-invalid=\"true\"]')?.focus(); return; }
        const response = { name: name.value.trim(), attendance: attendance(), guests: attendance() === 'yes' ? count.valueAsNumber : 0, dietary: attendance() === 'yes' ? dietary.value.trim() : '' };
        try {
          localStorage.setItem(storageKey, JSON.stringify(response));
          document.getElementById('save-error').hidden = true;
          showConfirmation(response);
        } catch { document.getElementById('save-error').hidden = false; }
      });
      document.getElementById('edit-response').addEventListener('click', () => {
        document.getElementById('confirmation').hidden = true;
        document.getElementById('form-view').hidden = false;
        document.querySelector('.form-section').setAttribute('aria-labelledby', 'rsvp-heading');
        name.focus();
      });
      try {
        const saved = JSON.parse(localStorage.getItem(storageKey));
        if (saved && typeof saved.name === 'string' && saved.name.trim() && ['yes', 'no'].includes(saved.attendance) && (saved.attendance === 'no' || Number.isSafeInteger(saved.guests) && saved.guests >= 1) && typeof saved.dietary === 'string') {
          name.value = saved.name;
          radios.find(radio => radio.value === saved.attendance).checked = true;
          count.value = saved.guests || 1;
          dietary.value = saved.dietary;
          updateAttendance();
          showConfirmation(saved, false);
        }
      } catch { /* The form remains usable when saved data is unavailable. */ }
    })();
  </script>
